func (this *Lbank) HandleBalance(client any, message map[string]any) {
	//
	//     {
	//         "data": {
	//             "asset": "114548.31881315",
	//             "assetCode": "usdt",
	//             "free": "97430.6739041",
	//             "freeze": "17117.64490905",
	//             "time": 1627300043270,
	//             "type": "ORDER_CREATE"
	//         },
	//         "SERVER": "V2",
	//         "type": "assetUpdate",
	//         "TS": "2021-07-26T19:48:03.548"
	//     }
	//
	var data any = this.SafeDict(message, "data", map[string]any{})
	var timestamp *int64 = this.Parse8601(this.SafeString(message, "TS"))
	var datetime *string = this.Iso8601(timestamp)
	ccxt.AddElementToObject(this.Balance, "info", data)
	ccxt.AddElementToObject(this.Balance, "timestamp", timestamp)
	ccxt.AddElementToObject(this.Balance, "datetime", datetime)
	var currencyId *string = this.SafeString(data, "assetCode")
	var code *string = this.SafeCurrencyCode(currencyId)
	var account map[string]any = this.Account()
	account["free"] = this.SafeString(data, "free")
	account["used"] = this.SafeString(data, "freeze")
	account["total"] = this.SafeString(data, "asset")
	if code != nil {
		ccxt.AddElementToObject(this.Balance, code, account)
	}
	this.Balance = this.SafeBalance(this.Balance)
	client.(ccxt.ClientInterface).Resolve(this.Balance, "balance")
}

