func (this *Lbank) HandleOrderBook(client any, message map[string]any) {
	//
	// request
	//    {
	//        "SERVER":"V2",
	//        "asks":[
	//           [
	//              42585.84,
	//              1.4422
	//           ],
	//           ...
	//        ],
	//        "bids":[
	//           [
	//              42585.83,
	//              1.8054
	//           ],
	//          ,,,
	//        ],
	//        "count":100,
	//        "type":"depth",
	//        "pair":"btc_usdt",
	//        "TS":"2024-01-16T08:26:00.413"
	//    }
	// subscribe
	//     {
	//         "depth": {
	//             "asks": [
	//                 [
	//                     0.0252,
	//                     0.5833
	//                 ],
	//                 [
	//                     0.025215,
	//                     4.377
	//                 ],
	//                 ...
	//             ],
	//             "bids": [
	//                 [
	//                     0.025135,
	//                     3.962
	//                 ],
	//                 [
	//                     0.025134,
	//                     3.46
	//                 ],
	//                 ...
	//             ]
	//         },
	//         "count": 100,
	//         "type": "depth",
	//         "pair": "eth_btc",
	//         "SERVER": "V2",
	//         "TS": "2019-06-28T17:49:22.722"
	//     }
	//
	var marketId *string = this.SafeString(message, "pair")
	var symbol *string = this.SafeSymbol(marketId)
	var orderBook any = this.SafeValue(message, "depth", message)
	var datetime *string = this.SafeString(message, "TS")
	var timestamp *int64 = this.Parse8601(datetime)
	// let orderbook = this.safeValue (this.orderbooks, symbol)
	if !(ccxt.InOp(this.Orderbooks, symbol)) {
		ccxt.AddElementToObject(this.Orderbooks, symbol, this.OrderBook(map[string]any{}))
	}
	var orderbook any = ccxt.GetValue(this.Orderbooks, symbol)
	var snapshot map[string]any = this.ParseOrderBook(orderBook, symbol, timestamp, "bids", "asks")
	orderbook.(ccxt.OrderBookInterface).Reset(snapshot)
	var messageHash string = "orderbook:" + *symbol
	client.(ccxt.ClientInterface).Resolve(orderbook, messageHash)
	messageHash = "fetchOrderbook:" + *symbol
	client.(ccxt.ClientInterface).Resolve(orderbook, messageHash)
}
func (this *Lbank) HandleErrorMessage(client any, message any) {
	//
	//    {
	//        SERVER: 'V2',
	//        message: "Missing parameter ['kbar']",
	//        status: 'error',
	//        TS: '2024-01-16T08:09:43.314'
	//    }
	//
	var errMsg *string = this.SafeString(message, "message", "")
	error := ccxt.ExchangeError(this.Id + " " + *errMsg)
	client.(ccxt.ClientInterface).Reject(error)
}
func (this *Lbank) HandlePingAsync(client any, message any) <-chan any {
	ch := make(chan any, 1)
	go this.handlePingBody(ch, client, message)
	return ch
}
func (this *Lbank) handlePingBody(ch chan any, client any, message any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	//
	//  { ping: 'a13a939c-5f25-4e06-9981-93cb3b890707', action: 'ping' }
	//
	// lbank closes the socket if this app-level ping is unanswered within a minute, but does not
	// reliably answer RFC 6455 ping frames; treat the inbound ping as a pong so keepAlive doesn't tear down a healthy socket
	client.(ccxt.ClientInterface).SetLastPong(this.Milliseconds())
	var pingId *string = this.SafeString(message, "ping")

	{
		func(this *Lbank) (ret_ any) {
			defer func() {
				if e := recover(); e != nil {
					if e == "break" {
						return
					}
					ret_ = func(this *Lbank) any {
						// catch block:
						this.OnError(client, e)
						return nil
					}(this)
				}
			}()
			// try block:

			ccxt.PanicOnError((<-client.(ccxt.ClientInterface).SendAsync(map[string]any{
				"action": "pong",
				"pong":   pingId,
			})))
			return nil
		}(this)

	}
	return nil
}
func (this *Lbank) HandleMessage(client any, message any) {
	var status *string = this.SafeString(message, "status")
	if status != nil && *status == "error" {
		this.HandleErrorMessage(client, message)
		return
	}
	var typeVar *string = this.SafeString2(message, "type", "action")
	if typeVar != nil && *typeVar == "ping" {
		this.Spawn(this.HandlePingAsync, client, message)
		return
	}
	var handlers map[string]any = map[string]any{
		"kbar":        this.HandleOHLCV,
		"depth":       this.HandleOrderBook,
		"trade":       this.HandleTrades,
		"tick":        this.HandleTicker,
		"orderUpdate": this.HandleOrders,
		"assetUpdate": this.HandleBalance,
	}
	var handler any = this.SafeValue(handlers, typeVar)
	if !ccxt.IsEqual(handler, nil) {
		ccxt.CallDynamically(handler, client, message)
	}
}
func (this *Lbank) AuthenticateAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.authenticateBody(ch, optionalArgs...)
	return ch
}
func (this *Lbank) authenticateBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	// single-flight leader election, see https://github.com/ccxt/ccxt/issues/29393:
	// concurrent watchOrders/watchBalance callers would each POST subscribe/get_key or
	// subscribe/refresh_key and burn rate limit on a subscribeKey that is immediately
	// overwritten. the flight lives in client.futures of this exchange's own ws client under
	// a key that is not a messageHash, and settles via client.resolve / client.reject only
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	this.CheckRequiredCredentials()
	var url *string = ccxt.SafeStringPtr(ccxt.GetValue(ccxt.GetValue(this.Urls, "api"), "ws"))
	var client ccxt.ClientInterface = this.Client(url)
	var now int64 = this.Milliseconds()
	var messageHash string = "authenticateFlight"
	if ccxt.InOp(client.(ccxt.ClientInterface).GetFutures(), messageHash) {
		// a flight is already in progress - wake when the leader settles
		// it: the subscribeKey is then in the bucket

		ccxt.PanicOnError((<-client.(ccxt.ClientInterface).Future(messageHash)))

		ch <- this.SafeString(this.SafeDict(client.(ccxt.ClientInterface).GetSubscriptions(), "authenticated"), "key")
		return nil
	}
	var future any = client.(ccxt.ClientInterface).ReusableFuture(messageHash)

	{
		func(this *Lbank) (ret_ any) {
			defer func() {
				if e := recover(); e != nil {
					if e == "break" {
						return
					}
					ret_ = func(this *Lbank) any {
						// catch block:
						// reject the flight - all waiters throw and the next caller
						// re-leads instead of deadlocking on a dead flight
						client.(ccxt.ClientInterface).Reject(e, messageHash)
						return nil
					}(this)
				}
			}()
			// try block:
			var authenticated any = this.SafeDict(client.(ccxt.ClientInterface).GetSubscriptions(), "authenticated")
			if authenticated == nil {

				response := (<-this.SpotPrivatePostSubscribeGetKey(params))
				ccxt.PanicOnError(response)
				//
				// {"result":true,"data":"4e9958623e6006bd7b13ff9f36c03b36132f0f8da37f70b14ff2c4eab1fe0c97","error_code":0,"ts":1705602277198}
				//
				var result *bool = this.SafeBool(response, "result")
				if result == nil || *result != true {
					panic(ccxt.ExchangeError(this.Id + " failed to get subscribe key"))
				}
				ccxt.AddElementToObject(client.(ccxt.ClientInterface).GetSubscriptions(), "authenticated", map[string]any{
					"key":     this.SafeString(response, "data"),
					"expires": this.Sum(now, 3300000),
				})
			} else {
				var expires *int64 = this.SafeInteger(authenticated, "expires", 0)
				if expires == nil || *expires < now {
					var request map[string]any = map[string]any{
						"subscribeKey": ccxt.GetValue(authenticated, "key"),
					}

					response := (<-this.SpotPrivatePostSubscribeRefreshKey(this.Extend(request, params)))
					ccxt.PanicOnError(response)
					//
					//    {"result": "true"}
					//
					var result *string = this.SafeString(response, "result")
					if result == nil || *result != "true" {
						panic(ccxt.ExchangeError(this.Id + " failed to refresh the SubscribeKey"))
					}
					ccxt.AddElementToObject(ccxt.GetValue(ccxt.GetValue(client, "subscriptions"), "authenticated"), "expires", this.Sum(now, 3300000)) // SubscribeKey lasts one hour, refresh it 5 minutes before it expires
				}
			}
			// settle the flight through the client so that every write to the
			// futures map happens inside the base class
			client.(ccxt.ClientInterface).Resolve(ccxt.GetValue(ccxt.GetValue(client.(ccxt.ClientInterface).GetSubscriptions(), "authenticated"), "key"), messageHash)
			return nil
		}(this)

	}
	// rethrows a rejected flight to the leader and attaches the handler
	// that keeps an alone leader from crashing on an unhandled rejection

	ccxt.PanicOnError(<-future.(*ccxt.Future).Await())

	ch <- this.SafeString(this.SafeDict(client.(ccxt.ClientInterface).GetSubscriptions(), "authenticated"), "key")
	return nil
}

func NewLbank(userConfig map[string]any) *Lbank {
	p := newLbank()
	p.Init(userConfig)
	return p
}

func (this *Lbank) Init(userConfig map[string]any) {
	this.base.Init(this.DeepExtend(this.Describe(), userConfig))
	this.Itf = this
	this.Exchange.DerivedExchange = this
}

